mapper.select:
/** slave-sleepuser-mapper.getSleepUserListByParam (휴면회원관리 목록 조회) */ SELECT A.USER_ID ,CASE WHEN IFNULL(A.LOGIN_DATE, '') != '' THEN DATE_FORMAT(A.LOGIN_DATE,'%Y-%m-%d') ELSE '' END AS LOGIN_DATE ,A.LOGIN_ID AS LOGIN_ID ,A.USER_NAME AS USER_NAME ,A.ADDRESS AS ADDRESS ,A.ADDRESS_DETAIL AS ADDRESS_DETAIL ,(SELECT SUM(CNTR_AMT) FROM G_CNTR WHERE USER_ID = A.USER_ID AND STTEMNT_PAY_DE IS NOT NULL AND DELETE_AT = 'N' AND CNTR_STTUS_CODE = '200') AS TOTAL_CNTR_AMT ,(SELECT SUM(CNTR_BLCE_POINT) FROM G_CNTR WHERE USER_ID = A.USER_ID AND STTEMNT_PAY_DE IS NOT NULL AND DELETE_AT = 'N' AND CNTR_STTUS_CODE = '200') AS TOTAL_CNTR_BLCE_POINT FROM (
SELECT U.USER_ID, U.LOGIN_DATE, U.LOGIN_ID, US.USER_NAME, US.ADDRESS, US.ADDRESS_DETAIL FROM OP_USER_SLEEP US INNER JOIN OP_USER U ON U.USER_ID = US.USER_ID AND U.STATUS_CODE = 4
ORDER BY U.LOGIN_DATE DESC
) A
